import { useRef, useState } from "react";
import { useNavigate } from "react-router";
import { motion, useMotionValue, useSpring, useTransform } from "motion/react";
import {
  Home,
  Search,
  ArrowLeft,
  Heart,
  RefreshCw,
  MoreHorizontal,
  type LucideIcon,
} from "lucide-react";

/**
 * RadialCommandWheel
 *
 * A hyper-realistic interaction showcase: a large tactile control knob that
 * physically expands into a premium radial command wheel on hover. Built with
 * spring physics only — icons feel generated by the wheel's surface, traveling
 * outward along radial paths with micro-overshoot. Lighting is cursor-reactive
 * and the surface breathes with a gentle ambient pulse.
 *
 * Two variants share the same engine:
 *  - "light": premium multi-layered neumorphism on a #F5F5F7 surface.
 *  - "dark":  VisionOS-style metallic knob with a layered "Bloom Glow".
 */

export interface Command {
  id: string;
  Icon: LucideIcon;
  label: string;
  run: (nav: ReturnType<typeof useNavigate>) => void;
}

/** Open the global Command Palette by re-emitting its ⌘K / Ctrl+K hotkey. */
function openCommandPalette() {
  document.dispatchEvent(
    new KeyboardEvent("keydown", { key: "k", metaKey: true, ctrlKey: true, bubbles: true }),
  );
}

export const DEFAULT_COMMANDS: Command[] = [
  { id: "home", Icon: Home, label: "Home", run: (nav) => nav("/") },
  { id: "search", Icon: Search, label: "Search", run: () => openCommandPalette() },
  { id: "back", Icon: ArrowLeft, label: "Back", run: (nav) => nav(-1) },
  { id: "heart", Icon: Heart, label: "Rewards", run: (nav) => nav("/rewards") },
  { id: "refresh", Icon: RefreshCw, label: "Refresh", run: () => window.location.reload() },
  { id: "more", Icon: MoreHorizontal, label: "Portal", run: (nav) => nav("/portal") },
];

const STAGE = 400; // overall interactive stage size
const RADIUS = 150; // distance icons travel from center
const KNOB = 120; // idle knob diameter
const ICON_SIZE = 48;

/** Spring profiles — low-bounce, physically connected, micro-overshoot. */
const wheelSpring = { type: "spring" as const, stiffness: 220, damping: 20, mass: 1 };
const knobSpring = { type: "spring" as const, stiffness: 360, damping: 24 };
const iconSpring = { type: "spring" as const, stiffness: 300, damping: 17, mass: 0.8 };

type Variant = "light" | "dark";

interface Palette {
  surface: string;
  primary: string;
  ringStroke: string;
  knobBg: string;
  knobShadow: string;
  iconBg: string;
  iconBgHover: string;
  iconBorder: string;
  iconColor: string;
}

const PALETTES: Record<Variant, Palette> = {
  light: {
    surface: "#F5F5F7",
    primary: "#C084FC",
    ringStroke: "rgba(192,132,252,0.40)",
    knobBg: "radial-gradient(circle at 38% 32%, #FFFFFF 0%, #FAFAFC 45%, #ECECF1 100%)",
    knobShadow: [
      "-18px -18px 40px rgba(255,255,255,0.95)",
      "20px 22px 48px rgba(0,0,0,0.14)",
      "8px 10px 22px rgba(0,0,0,0.08)",
      "inset -3px -3px 8px rgba(255,255,255,0.9)",
      "inset 3px 3px 10px rgba(0,0,0,0.06)",
    ].join(", "),
    iconBg: "rgba(192,132,252,0.10)",
    iconBgHover: "rgba(192,132,252,0.24)",
    iconBorder: "1px solid rgba(192,132,252,0.22)",
    iconColor: "#7C3AED",
  },
  dark: {
    surface: "#0E1320",
    primary: "#A855F7",
    ringStroke: "rgba(168,85,247,0.40)",
    knobBg:
      "radial-gradient(circle at 36% 30%, #2A3346 0%, #161D2C 45%, #080B14 100%)",
    knobShadow: [
      "0px 30px 70px rgba(0,0,0,0.7)",
      "inset 0px 2px 5px rgba(255,255,255,0.12)",
      "inset 0px -6px 14px rgba(0,0,0,0.6)",
      "inset 0px 0px 1px rgba(255,255,255,0.25)",
    ].join(", "),
    iconBg: "rgba(255,255,255,0.06)",
    iconBgHover: "rgba(168,85,247,0.22)",
    iconBorder: "1px solid rgba(255,255,255,0.10)",
    iconColor: "#FFFFFF",
  },
};

export function Wheel({
  variant,
  commands = DEFAULT_COMMANDS,
}: {
  variant: Variant;
  commands?: Command[];
}) {
  const ICONS = commands;
  const p = PALETTES[variant];
  const isDark = variant === "dark";
  const navigate = useNavigate();
  const [open, setOpen] = useState(false);
  const [hovered, setHovered] = useState<string | null>(null);
  const ref = useRef<HTMLDivElement>(null);

  // Cursor-reactive lighting: tracks pointer relative to the control center.
  const mx = useMotionValue(0);
  const my = useMotionValue(0);
  const sx = useSpring(mx, { stiffness: 140, damping: 18 });
  const sy = useSpring(my, { stiffness: 140, damping: 18 });
  // Subtle 3D tilt toward the cursor.
  const rotateX = useTransform(sy, [-1, 1], [10, -10]);
  const rotateY = useTransform(sx, [-1, 1], [-10, 10]);
  // Specular highlight follows the cursor across the surface.
  const glowX = useTransform(sx, [-1, 1], [28, 72]);
  const glowY = useTransform(sy, [-1, 1], [26, 74]);
  // Center dash rotates to track the cursor direction on hover.
  const dashRotate = useTransform([sx, sy], ([x, y]: number[]) =>
    x === 0 && y === 0 ? 0 : (Math.atan2(y, x) * 180) / Math.PI + 90,
  );
  const surfaceHighlight = useTransform(
    [glowX, glowY],
    ([gx, gy]: number[]) =>
      `radial-gradient(circle at ${gx}% ${gy}%, ${
        isDark ? "rgba(192,132,252,0.28)" : "rgba(255,255,255,0.95)"
      } 0%, transparent 55%)`,
  );

  function handleMove(e: React.MouseEvent) {
    const el = ref.current;
    if (!el) return;
    const r = el.getBoundingClientRect();
    mx.set(((e.clientX - r.left) / r.width) * 2 - 1);
    my.set(((e.clientY - r.top) / r.height) * 2 - 1);
  }

  function reset() {
    mx.set(0);
    my.set(0);
    setOpen(false);
    setHovered(null);
  }

  return (
    <motion.div
      ref={ref}
      onHoverEnd={reset}
      onMouseMove={handleMove}
      className="relative flex items-center justify-center"
      style={{ width: STAGE, height: STAGE, perspective: 1000 }}
      // Ambient breathing / float.
      animate={{ y: [0, -5, 0] }}
      transition={{ duration: 4.5, repeat: Infinity, ease: "easeInOut" }}
    >
      {/* Large diffused ambient background glow (bloom). */}
      <motion.div
        className="pointer-events-none absolute rounded-full"
        style={{
          width: 360,
          height: 360,
          background: isDark
            ? "radial-gradient(circle, rgba(124,58,237,0.45) 0%, rgba(124,58,237,0.12) 40%, transparent 70%)"
            : "radial-gradient(circle, rgba(192,132,252,0.30) 0%, transparent 70%)",
          filter: "blur(28px)",
        }}
        animate={{
          opacity: open ? 1 : isDark ? 0.18 : 0,
          scale: open ? [1, 1.06, 1] : 0.7,
        }}
        transition={
          open
            ? { duration: 3.2, repeat: Infinity, ease: "easeInOut" }
            : wheelSpring
        }
      />

      {/* Core bloom glow right behind the knob (dark side hero lighting). */}
      <motion.div
        className="pointer-events-none absolute rounded-full"
        style={{
          width: 180,
          height: 180,
          background: isDark
            ? "radial-gradient(circle, rgba(168,85,247,0.7) 0%, rgba(168,85,247,0.18) 45%, transparent 70%)"
            : "radial-gradient(circle, rgba(192,132,252,0.35) 0%, transparent 70%)",
          filter: "blur(14px)",
        }}
        animate={{ opacity: open ? 1 : isDark ? 0.4 : 0, scale: open ? 1.1 : 0.8 }}
        transition={wheelSpring}
      />

      {/* Expanding outer rings — grow out of the knob, micro-rotating. */}
      <motion.div
        className="pointer-events-none absolute rounded-full"
        style={{
          border: `1.5px solid ${p.ringStroke}`,
          boxShadow: isDark ? `0 0 22px ${p.ringStroke}` : "none",
        }}
        initial={false}
        animate={{
          width: open ? STAGE - 40 : KNOB,
          height: open ? STAGE - 40 : KNOB,
          opacity: open ? 1 : 0,
          rotate: open ? 6 : 0,
        }}
        transition={wheelSpring}
      />
      <motion.div
        className="pointer-events-none absolute rounded-full"
        style={{ border: `1px solid ${p.ringStroke}` }}
        initial={false}
        animate={{
          width: open ? STAGE - 110 : KNOB,
          height: open ? STAGE - 110 : KNOB,
          opacity: open ? 0.55 : 0,
          rotate: open ? -4 : 0,
        }}
        transition={{ ...wheelSpring, delay: open ? 0.04 : 0 }}
      />

      {/* Radial icons — emerge from center and travel outward with overshoot. */}
      {ICONS.map((cmd, i) => {
        const { id, Icon, label, run } = cmd;
        const angle = (i / ICONS.length) * Math.PI * 2 - Math.PI / 2;
        const ux = Math.cos(angle);
        const uy = Math.sin(angle);
        const x = open ? ux * RADIUS : 0;
        const y = open ? uy * RADIUS : 0;
        const isHot = hovered === id;
        return (
          <motion.button
            key={id}
            type="button"
            aria-label={label}
            onHoverStart={() => setHovered(id)}
            onHoverEnd={() => setHovered((h) => (h === id ? null : h))}
            onClick={() => run(navigate)}
            className="absolute flex cursor-pointer items-center justify-center rounded-full"
            style={{
              width: ICON_SIZE,
              height: ICON_SIZE,
              border: p.iconBorder,
              backdropFilter: "blur(14px)",
              WebkitBackdropFilter: "blur(14px)",
              color: p.iconColor,
            }}
            initial={false}
            animate={{
              x,
              y,
              scale: open ? (isHot ? 1.18 : 1) : 0.4,
              opacity: open ? 1 : 0,
              rotate: isHot ? 8 : 0,
              backgroundColor: isHot ? p.iconBgHover : p.iconBg,
              boxShadow: isHot
                ? `0 0 28px ${isDark ? "rgba(168,85,247,0.6)" : "rgba(192,132,252,0.5)"}`
                : "0 4px 12px rgba(0,0,0,0.12)",
            }}
            transition={{ ...iconSpring, delay: open ? i * 0.045 : 0 }}
          >
            <Icon size={20} strokeWidth={2} style={{ opacity: 0.92 }} />
          </motion.button>
        );
      })}

      {/* Hover pointer — a small arrow + label that points at the hovered icon. */}
      {ICONS.map((cmd, i) => {
        const angle = (i / ICONS.length) * Math.PI * 2 - Math.PI / 2;
        const ux = Math.cos(angle);
        const uy = Math.sin(angle);
        const isHot = hovered === cmd.id && open;
        // Sits just outside the icon, along the same radial direction.
        const lx = ux * (RADIUS + ICON_SIZE / 2 + 22);
        const ly = uy * (RADIUS + ICON_SIZE / 2 + 22);
        // Caret rotates to point back toward the icon (inward).
        const caretDeg = (angle * 180) / Math.PI - 90;
        return (
          <motion.div
            key={`tip-${cmd.id}`}
            className="pointer-events-none absolute flex items-center justify-center"
            style={{ x: lx, y: ly }}
            initial={false}
            animate={{ opacity: isHot ? 1 : 0, scale: isHot ? 1 : 0.6 }}
            transition={{ type: "spring", stiffness: 400, damping: 26 }}
          >
            <div className="relative flex items-center justify-center">
              <span
                className="whitespace-nowrap rounded-full px-2.5 py-1"
                style={{
                  fontSize: 11,
                  fontWeight: 600,
                  letterSpacing: "0.02em",
                  color: isDark ? "#F3E8FF" : "#6D28D9",
                  background: isDark
                    ? "rgba(168,85,247,0.18)"
                    : "rgba(192,132,252,0.16)",
                  border: `1px solid ${p.ringStroke}`,
                  backdropFilter: "blur(8px)",
                  WebkitBackdropFilter: "blur(8px)",
                }}
              >
                {cmd.label}
              </span>
              {/* Caret pointing toward the icon. */}
              <span
                className="absolute"
                style={{
                  width: 0,
                  height: 0,
                  left: "50%",
                  top: "50%",
                  marginLeft: -ux * 26 - 4,
                  marginTop: -uy * 26 - 4,
                  borderLeft: "4px solid transparent",
                  borderRight: "4px solid transparent",
                  borderBottom: `6px solid ${p.primary}`,
                  transform: `rotate(${caretDeg}deg)`,
                }}
              />
            </div>
          </motion.div>
        );
      })}

      {/* Center pointer — arrow + label that points at the central knob. */}
      <motion.div
        className="pointer-events-none absolute flex flex-col items-center"
        style={{ y: -(KNOB / 2 + 30) }}
        initial={false}
        animate={{
          opacity: hovered === "center" && open ? 1 : 0,
          scale: hovered === "center" && open ? 1 : 0.6,
        }}
        transition={{ type: "spring", stiffness: 400, damping: 26 }}
      >
        <span
          className="whitespace-nowrap rounded-full px-2.5 py-1"
          style={{
            fontSize: 11,
            fontWeight: 600,
            letterSpacing: "0.02em",
            color: isDark ? "#F3E8FF" : "#6D28D9",
            background: isDark ? "rgba(168,85,247,0.18)" : "rgba(192,132,252,0.16)",
            border: `1px solid ${p.ringStroke}`,
            backdropFilter: "blur(8px)",
            WebkitBackdropFilter: "blur(8px)",
          }}
        >
          Menu
        </span>
        <span
          style={{
            width: 0,
            height: 0,
            marginTop: 2,
            borderLeft: "4px solid transparent",
            borderRight: "4px solid transparent",
            borderTop: `6px solid ${p.primary}`,
          }}
        />
      </motion.div>

      {/* The knob — origin of the whole interaction; micro-rotates on hover. */}
      <motion.div
        onHoverStart={() => { setOpen(true); setHovered("center"); }}
        onHoverEnd={() => setHovered((h) => (h === "center" ? null : h))}
        className="relative flex cursor-pointer items-center justify-center rounded-full"
        style={{
          width: KNOB,
          height: KNOB,
          background: p.knobBg,
          boxShadow: p.knobShadow,
          rotateX,
          rotateY,
          transformStyle: "preserve-3d",
        }}
        animate={{ scale: open ? 0.62 : 1, rotate: open ? 4 : 0 }}
        transition={knobSpring}
      >
        {/* Cursor-following specular highlight. */}
        <motion.div
          className="pointer-events-none absolute inset-0 rounded-full"
          style={{ background: surfaceHighlight, mixBlendMode: isDark ? "screen" : "normal" }}
        />
        {/* Razor-sharp edge highlight (dark) / soft rim (light). */}
        <div
          className="pointer-events-none absolute inset-0 rounded-full"
          style={{
            boxShadow: isDark
              ? "inset 0 1px 1px rgba(255,255,255,0.3)"
              : "inset 0 2px 3px rgba(255,255,255,0.9)",
          }}
        />
        {/* Center indicator. */}
        <motion.div
          className="pointer-events-none absolute flex items-start justify-center"
          style={{ width: KNOB, height: KNOB, rotate: open ? dashRotate : 0 }}
        >
          <motion.div
            className="rounded-full"
            style={{
              width: 5,
              height: 18,
              marginTop: KNOB / 2 - 30,
              background: p.primary,
              boxShadow: isDark ? `0 0 10px ${p.primary}` : "none",
            }}
            animate={{ opacity: 1, scale: open ? 0.85 : 1 }}
            transition={knobSpring}
          />
        </motion.div>
      </motion.div>
    </motion.div>
  );
}

export default function RadialCommandWheel() {
  return (
    <div className="min-h-screen w-full">
      <div className="grid min-h-screen" style={{ gridTemplateColumns: "1fr 1fr" }}>
        {/* Left — Light mode */}
        <div
          className="relative flex items-center justify-center"
          style={{ background: PALETTES.light.surface }}
        >
          <span
            className="absolute left-10 top-9"
            style={{
              color: "#666666",
              fontWeight: 600,
              fontSize: 16,
              letterSpacing: "0.02em",
            }}
          >
            Light Mode
          </span>
          <Wheel variant="light" />
        </div>

        {/* Right — Dark mode */}
        <div
          className="relative flex items-center justify-center"
          style={{ background: PALETTES.dark.surface }}
        >
          <span
            className="absolute right-10 top-9"
            style={{
              color: "#E5E7EB",
              fontWeight: 600,
              fontSize: 16,
              letterSpacing: "0.02em",
            }}
          >
            Dark Mode
          </span>
          <Wheel variant="dark" />
        </div>
      </div>
    </div>
  );
}
